// NEXO Studio 4.1 - servidor monofichero para desplegar desde un celular.
// Contiene un empaquetado íntegro del backend y la interfaz oficiales de NEXO 4.1.
// No contiene credenciales, modelos de IA ni datos de usuarios.
// Requiere Node.js 22+.
'use strict';
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const zlib = require('node:zlib');
const bundle = '';
const files = JSON.parse(zlib.gunzipSync(Buffer.from(bundle, 'base64')).toString('utf8'));
const folder = fs.mkdtempSync(path.join(os.tmpdir(), 'nexo-studio-'));
for (const [rel, data] of Object.entries(files)) {
  const dest = path.join(folder, rel);
  fs.mkdirSync(path.dirname(dest), {recursive:true});
  fs.writeFileSync(dest, Buffer.from(data, 'base64'), {mode:0o600});
}
process.env.HOST ||= '0.0.0.0';
const nexo = require(path.join(folder, 'server.js'));
nexo.init().then(() => {
  const host = process.env.HOST || '0.0.0.0';
  const port = Number(process.env.PORT || 10000);
  nexo.server.listen(port, host, () => {
    console.log(`NEXO Studio iniciado en ${host}:${port}`);
  });
  setInterval(() => {
    void nexo.checkDaily().catch(e => console.error('Reunión diaria:', e.message));
    void nexo.checkRoutines().catch(e => console.error('Automatización:', e.message));
  }, 30000);
  void nexo.checkDaily();
  void nexo.checkRoutines();
}).catch(e => {
  console.error('Fallo al iniciar NEXO:', e);
  process.exitCode = 1;
});
